// PROTOTYPE: converts the private japanese-batch-kitchen corpus into the ADR 0006 shape the conductor reads,
// inferring equipment and attention from step text the way the M0 importer will. Output is git-ignored.
//
//   node prototype/conductor/convert.js "C:\path\to\japanese-batch-kitchen"
const fs = require('fs');
const path = require('path');

const src = process.argv[2];
if (!src) { console.error('usage: node convert.js <japanese-batch-kitchen folder>'); process.exit(1); }
const { R } = require(path.join(path.resolve(src), 'scripts', 'recipes.js'));

const HANDS = /\b(fry|fried|sauté|brown|sear|stir|toast|grill|glaze|scramble|roll|flip|toss)/;
function infer(r, s, stepsSoFar) {
  const lc = s[0].toLowerCase();
  const u = r.u || [];
  const pot = u.includes('pot') ? 'pot' : u.includes('smallpot') ? 'smallpot' : 'pot';
  let kinds = [];
  if (/microwave/.test(lc)) kinds = ['microwave'];
  else if (u.includes('deepfry') && /\b(deep|fry|fried)\b|\d{3} ?°/.test(lc) && !/stir-fry|pan-fry/.test(lc)) kinds = ['deepfry'];
  else if (/\b(fry|fried|sauté|brown|sear|stir-fry|glaze|toast|grill|scramble)\b|\bpan\b/.test(lc)) kinds = ['pan'];
  else if (/\b(boil|simmer|blanch|poach|steam|bring to)\b|\bpot\b/.test(lc)) kinds = [pot];
  else if (/\b(add|return|reduce|cook|toss|stir|until|heat|warm)\b/.test(lc)) {
    // continuation: no heat word of its own, but its main input is on the hob
    const main = s[1].find(x => typeof x === 'string');
    const prev = main && stepsSoFar[+main.slice(1)];
    if (prev && prev.equipment.length && prev.equipment[0] !== 'microwave') kinds = [prev.equipment[0]];
  }
  let timer;
  if (s[2]) {
    const range = lc.match(/(\d+(?:\.\d+)?)\s*[–-]\s*(\d+(?:\.\d+)?)\s*min/);
    timer = { min: s[2], max: s[2] + (range ? +range[2] - +range[1] : 0), attention: HANDS.test(lc) && kinds.length ? 'hands' : 'walk' };
  }
  return { equipment: kinds, timer };
}

const out = R.map(r => {
  const steps = [];
  r.s.forEach((s, i) => {
    const inf = infer(r, s, steps);
    steps.push({
      id: 's' + i, text: s[0],
      inputs: s[1].filter(x => typeof x === 'string'),
      ings: s[1].filter(x => typeof x === 'number'),
      ...inf,
    });
  });
  return { id: 'jbk' + r.d, name: r.n, handsOnMin: r.t, batch: r.b, keep: r.k, category: r.c, utensils: r.u,
    ingredients: r.i.map(([key, qty, unit]) => ({ key, qty, unit })), steps };
});

const file = path.join(__dirname, 'corpus.local.js');
fs.writeFileSync(file, '// Generated by convert.js from the private japanese-batch-kitchen corpus. Git-ignored: never commit (ADR 0001).\n' +
  '(function (root) { const C = ' + JSON.stringify(out) + ';\n if (typeof module === "object" && module.exports) module.exports = C; else root.EVEY_CORPUS = C; })(typeof self !== "undefined" ? self : this);\n');
const st = out.flatMap(r => r.steps);
const k = {}; st.forEach(s => s.equipment.forEach(e => k[e] = (k[e] || 0) + 1));
console.log(`wrote ${path.basename(file)}: ${out.length} recipes, ${st.length} steps; equipment ${JSON.stringify(k)}; timers walk ${st.filter(s => s.timer && s.timer.attention === 'walk').length} hands ${st.filter(s => s.timer && s.timer.attention === 'hands').length}`);
